//! Zeroclaw route helpers backed by DbusPassthrough on the canonical plugin tree.

use anyhow::{bail, Result};
use op_grpc_bridge::proto::dbus_passthrough_client::DbusPassthroughClient;
use op_grpc_bridge::proto::DbusGetPropertyRequest;
use op_identity::read_sled;
use simd_json::prelude::*;
use tonic::metadata::MetadataValue;
use tonic::service::Interceptor;
use tonic::Request;

use crate::projection_client::ProjectionCache;

const PROJECTED_OBJECT_IFACE: &str = "org.opdbus.ProjectedObjectV1";
const ZEROCLAW_PLUGIN_ID: &str = "zeroclaw";

#[derive(Debug, Clone)]
pub struct ZeroclawRoute {
    pub provider: String,
    pub upstream_provider: String,
    pub transport: Option<String>,
    pub model: String,
    pub hint: Option<String>,
    pub kind: Option<String>,
    pub status: String,
    pub available: bool,
    pub status_reason: Option<String>,
    pub source: Option<String>,
}

impl ZeroclawRoute {
    fn from_value(value: &simd_json::OwnedValue) -> Option<Self> {
        let model = value.get("model")?.as_str()?.to_string();
        let provider = value
            .get("provider")
            .and_then(|v| v.as_str())
            .unwrap_or("zeroclaw")
            .to_string();
        let upstream_provider = value
            .get("upstream_provider")
            .and_then(|v| v.as_str())
            .unwrap_or(&provider)
            .to_string();
        let status = value
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("declared")
            .to_string();
        let available = value
            .get("available")
            .and_then(|v| v.as_bool())
            .unwrap_or_else(|| status == "available");

        Some(Self {
            provider,
            upstream_provider,
            transport: value
                .get("transport")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            model,
            hint: value
                .get("hint")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            kind: value
                .get("kind")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            status,
            available,
            status_reason: value
                .get("status_reason")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            source: value
                .get("source")
                .and_then(|v| v.as_str())
                .map(str::to_string),
        })
    }
}

#[derive(Clone)]
struct SledInterceptor {
    footprint: String,
    trace_id: String,
}

impl Interceptor for SledInterceptor {
    fn call(&mut self, mut request: Request<()>) -> std::result::Result<Request<()>, tonic::Status> {
        let footprint = MetadataValue::try_from(self.footprint.as_str())
            .map_err(|e| tonic::Status::internal(e.to_string()))?;
        let trace_id = MetadataValue::try_from(self.trace_id.as_str())
            .map_err(|e| tonic::Status::internal(e.to_string()))?;
        request
            .metadata_mut()
            .insert("x-ghostbridge-footprint", footprint);
        request
            .metadata_mut()
            .insert("x-ghostbridge-trace-id", trace_id);
        Ok(request)
    }
}

fn sled_interceptor() -> Option<SledInterceptor> {
    let (ptr, _mmap) = read_sled().ok()?;
    // SAFETY: `read_sled` maps a full IdentitySled from the canonical shm file,
    // and `_mmap` is kept alive while the copied fields are read.
    let sled = unsafe { &*ptr };
    if sled.hashed_footprint == [0u8; 32] || sled.trace_id == [0u8; 16] {
        return None;
    }
    Some(SledInterceptor {
        footprint: hex::encode(sled.hashed_footprint),
        trace_id: sled.trace_id_hex(),
    })
}

async fn plugin_state_from_dbus_passthrough(plugin_id: &str) -> Option<simd_json::OwnedValue> {
    let addr = std::env::var("ZEROCLAW_GRPC_BRIDGE_ADDR")
        .or_else(|_| std::env::var("ZEROCLAW_GRPC_ADDR"))
        .unwrap_or_else(|_| "http://127.0.0.1:8090".to_string());
    let interceptor = sled_interceptor()?;
    let channel = tonic::transport::Channel::from_shared(addr)
        .ok()?
        .connect()
        .await
        .ok()?;
    let mut client = DbusPassthroughClient::with_interceptor(channel, interceptor);
    let response = client
        .get(DbusGetPropertyRequest {
            bus: "session".to_string(),
            destination: op_core::config::OPDBUS_BUS_NAME.to_string(),
            path: format!("{}/{}", op_core::config::PLUGIN_BASE_PATH, plugin_id),
            interface: PROJECTED_OBJECT_IFACE.to_string(),
            property: "JsonData".to_string(),
        })
        .await
        .ok()?
        .into_inner();
    if !response.success {
        return None;
    }

    let outer: serde_json::Value = serde_json::from_str(&response.json_value).ok()?;
    let raw = outer.as_str().unwrap_or(&response.json_value);
    let mut bytes = raw.as_bytes().to_vec();
    simd_json::to_owned_value(&mut bytes).ok()
}

pub async fn plugin_state() -> Option<simd_json::OwnedValue> {
    plugin_state_from_dbus_passthrough(ZEROCLAW_PLUGIN_ID).await
}

pub async fn routes(_cache: &ProjectionCache) -> Option<Vec<ZeroclawRoute>> {
    let zeroclaw = plugin_state().await?;
    let route_values = zeroclaw.get("model_routes")?.as_array()?;
    Some(
        route_values
            .iter()
            .filter_map(ZeroclawRoute::from_value)
            .collect(),
    )
}

pub async fn route_for_model(cache: &ProjectionCache, model: &str) -> Option<ZeroclawRoute> {
    routes(cache)
        .await?
        .into_iter()
        .find(|route| route.model == model)
}

pub async fn ensure_model_available(cache: &ProjectionCache, model: &str) -> Result<()> {
    if let Some(route) = route_for_model(cache, model).await {
        if !route.available {
            let reason = route
                .status_reason
                .unwrap_or_else(|| "route is not available".to_string());
            bail!(
                "Zeroclaw route '{}' is {} but not available: {}",
                model,
                route.status,
                reason
            );
        }
    }

    Ok(())
}

